def policy(obs, P):
    x = obs[0]
    v = obs[1]
    if x > P['goal']:
        return 1
    if x <= P['left_wall']:
        return 2
    if v <= P['v_neg']:
        if x <= P['mid_neg']:
            return 0
        else:
            return 1
    else:
        if v > P['v_high']:
            return 2
        else:
            if x <= P['low']:
                return 2
            else:
                if x > P['high_pos']:
                    return 2
                else:
                    if x <= P['mid2']:
                        return 1
                    else:
                        return 0
